CREATE TABLE roles (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(40) NOT NULL UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(255) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, full_name VARCHAR(255) NOT NULL, phone VARCHAR(40), enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_users_email(email));
CREATE TABLE user_roles (user_id BIGINT NOT NULL, role_id BIGINT NOT NULL, PRIMARY KEY(user_id, role_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE categories (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, slug VARCHAR(160) NOT NULL UNIQUE, image_url VARCHAR(500), parent_id BIGINT, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_category_slug(slug), FOREIGN KEY(parent_id) REFERENCES categories(id));
CREATE TABLE products (id BIGINT PRIMARY KEY AUTO_INCREMENT, category_id BIGINT, name VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, description TEXT, price DECIMAL(12,2) NOT NULL, compare_at_price DECIMAL(12,2), active BOOLEAN NOT NULL DEFAULT TRUE, featured BOOLEAN NOT NULL DEFAULT FALSE, best_seller BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_product_slug(slug), INDEX idx_product_name(name), INDEX idx_product_price(price), FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE product_images (product_id BIGINT NOT NULL, image_urls VARCHAR(700), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE product_variants (id BIGINT PRIMARY KEY AUTO_INCREMENT, product_id BIGINT NOT NULL, sku VARCHAR(100) NOT NULL UNIQUE, size VARCHAR(20), color VARCHAR(60), stock INT NOT NULL DEFAULT 0, price_override DECIMAL(12,2), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_variant_sku(sku), INDEX idx_variant_stock(stock), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE addresses (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT, full_name VARCHAR(255), phone VARCHAR(40), line1 VARCHAR(255), line2 VARCHAR(255), city VARCHAR(120), state VARCHAR(120), postal_code VARCHAR(20), country VARCHAR(80), default_address BOOLEAN DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE cart_items (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT, variant_id BIGINT, quantity INT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uk_cart_user_variant(user_id, variant_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(variant_id) REFERENCES product_variants(id));
CREATE TABLE coupons (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(60) NOT NULL UNIQUE, type VARCHAR(30) NOT NULL, value DECIMAL(12,2) NOT NULL, minimum_order_value DECIMAL(12,2), expires_at TIMESTAMP NULL, active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE orders (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_number VARCHAR(60) NOT NULL UNIQUE, user_id BIGINT, status VARCHAR(40), subtotal DECIMAL(12,2) NOT NULL, tax DECIMAL(12,2) NOT NULL, shipping DECIMAL(12,2) NOT NULL, total DECIMAL(12,2) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_orders_user_created(user_id, created_at), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE order_items (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT, variant_id BIGINT, product_name VARCHAR(255), sku VARCHAR(100), quantity INT, unit_price DECIMAL(12,2) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(variant_id) REFERENCES product_variants(id));
CREATE TABLE payments (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT UNIQUE, provider VARCHAR(40), provider_order_id VARCHAR(120), provider_payment_id VARCHAR(120), status VARCHAR(40), amount DECIMAL(12,2) NOT NULL, currency VARCHAR(10), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_payment_provider(provider, provider_payment_id), FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE reviews (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT, product_id BIGINT, rating INT NOT NULL, comment TEXT, approved BOOLEAN DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uk_review_user_product(user_id, product_id), INDEX idx_reviews_product(product_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE wishlist_items (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT, product_id BIGINT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uk_wishlist_user_product(user_id, product_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE banners (id BIGINT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(255), eyebrow VARCHAR(120), image_url VARCHAR(700), cta_label VARCHAR(80), cta_url VARCHAR(255), sort_order INT DEFAULT 0, active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
